for code,templates in TEXT.items():
 out=M[code]
 for key,source in S.items():
  if not isinstance(source,str)or not key.startswith('challenge.'):continue
  new=None;n=re.search(r'\d+',source);n=n[0]if n else None
  patterns=[(1,r'Kill (\d+) enemies'),(2,r'(?:Kill (\d+) enemies with headshots|Get (\d+) headshot kills)'),(3,r'Land (\d+) headshot kills in a single raid'),(4,r'Kill (\d+) enemies on iron sights'),(5,r'Kill (\d+) enemies with arm damage'),(6,r'Kill (\d+) enemies with leg damage'),(7,r'Kill (\d+) enemies with stomach damage'),(8,r'(?:Kill (\d+) enemies with grenades|Get (\d+) grenade kills)'),(9,r'Get (\d+) melee kills'),(10,r'Extract successfully (\d+) times'),(13,r'Extract as a Scav (\d+) times')]
  for index,pattern in patterns:
   if re.fullmatch(pattern,source):new=templates[index].format(n=n)
  for index,literal in [(11,'Extract from a raid alive'),(12,'Extract successfully from any map')]:
   if source==literal:new=templates[index]
  for index,pattern in [(14,r'Extract with (₽[\d,]+) of loot in one raid'),(15,r'Haul out (₽[\d,]+) of loot today'),(16,r'Haul out (₽[\d,]+) of loot this weekend')]:
   match=re.fullmatch(pattern,source)
   if match:new=templates[index].format(v=match[1])
  match=re.fullmatch(r'Kill (\d+) enemies from (\d+)m or further( in a single raid)?',source)
  if match:new=templates[18 if match[3]else 17].format(n=match[1],m=match[2])
  for index,literal in [(1,'Kill an enemy with a grenade'),(1,'Get a grenade kill'),(2,'Get a melee kill'),(3,'Kill an enemy with arm damage')]:
   if source==literal:new=SINGULAR[code][index]
  match=re.fullmatch(r'Kill an enemy from (\d+)m or further',source)
  if match:new=SINGULAR[code][4].format(m=match[1])
  if new:out[key]=new
(P/'manual-overrides.json').write_text(json.dumps(M,ensure_ascii=False,indent=2)+'\n')
print('Editorial objectives prepared:',sum(len(x)for x in M.values()))
